import openpyxl
from openpyxl.utils import get_column_letter
wb=openpyxl.load_workbook('/root/SUT-2024_eng.xlsx', data_only=True)
sh=wb['USE (38-38)-2024']
# find header row for columns 2 and 3
for r in [2,3]:
    row=[(get_column_letter(c), sh.cell(r,c).value) for c in range(1,55)]
    print('row',r)
    for col,val in row:
        if val is not None:
            print(col,val)
    print('---')
# find column with 'Total uses'
for row in sh.iter_rows():
    for cell in row:
        if isinstance(cell.value,str) and 'Total' in cell.value and 'use' in cell.value.lower():
            print(cell.coordinate, cell.value)
